  if(Array.isArray(a.steps)){ steps=a.steps; }
  else { steps=[]; if(a.acao==='alarme'){ const al=a.alarme||{}; steps.push({tipo:'alarme',msg:al.msg||a.name||'Alarme',nivel:al.nivel||'alerta',voz:al.voz!==false,email:!!al.email}); }
    else if(a.acao==='ligar'||a.acao==='desligar'){ targets(a).forEach(id=>steps.push({tipo:'acao',itemId:id,on:a.acao==='ligar'})); } }
  // executa em sequência, respeitando os delays
  const rid=a.id, envId=a.envId;
  function runStep(st){ const o=[null,null,null,null];
    if(st.tipo==='alarme'){ const env=envs.find(e=>e.id===envId); const al={id:'alm_'+Date.now()+'_'+Math.floor(Math.random()*1000),ts:Date.now(),msg:st.msg||'Alarme',nivel:st.nivel||'alerta',voz:st.voz!==false,email:!!st.email,rule:a.name,env:env?env.name:''};
      o[2]={topic:'alarme',payload:al}; if(al.email) o[3]={topic:'[Alarme] '+String(al.nivel).toUpperCase()+': '+al.msg, payload:al.msg+'\n\n'+(al.env||'')+'  '+spStr(al.ts), _alarm:al};
    } else if(st.tipo==='acao'){
      var _ids=(typeof st.itemId==='string' && st.itemId.indexOf('grupo:')===0) ? (Array.isArray(st.grupoIds)?st.grupoIds:[]) : [st.itemId];
      _ids.forEach(function(tid){ const mt=meta(tid); if(!mt) return; const oo=[null,null,null,null,null];
        if(mt.kind==='ac'){ const useCmd=(st.cmd!=null&&st.cmd!==''); const cid=useCmd?Number(st.cmd):(st.on?mt.on:mt.off); if(cid==null) return; oo[0]={payload:{controller:mt.controller,action:useCmd?'raw':(st.on?'on':'off'),commandId:cid,itemId:tid,_auto:rid}}; }
        else oo[1]={payload:{deviceName:mt.deviceName,id:mt.id,channel:mt.channel,on:(mt.invert?!st.on:!!st.on),_auto:rid}};
        node.send(oo); });
      return;
    } else return;
    node.send(o);
  }
  let off=0;
  steps.forEach(st=>{ if(st.tipo==='delay'){ off += (Number(st.seg)||0)*1000; return; } if(off<=0){ runStep(st); } else { setTimeout(function(){ runStep(st); }, off); } });
});
global.set('autostate',st); return [null, null, ui, null];

const a=msg.payload; if(!Array.isArray(a)) return null;
