const a=msg.payload; if(!Array.isArray(a)) return null;
global.set('feriados',a);
msg.payload=JSON.stringify(a,null,2); msg.filename='/data/feriados.json'; return msg;

let a=[]; try{ a=JSON.parse(msg.payload||'[]'); }catch(e){}
if(!Array.isArray(a)) a=[];
global.set('feriados',a);
return {topic:'feriadosload', payload:a};

// Monta payload base64 {to,subject,body} e grava em arquivo p/ o mailer Node ler.
var to = (msg.to && String(msg.to).trim()) || flow.get('alarm_email_to') || '';
var rcpts = to.split(/[,;\s]+/).map(function(x){return x.trim();}).filter(function(x){ return /^[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}$/.test(x); });
