const cat=global.get('catalog');
if(cat && (cat.deviceIds || cat.acs || cat.meters)) { return {topic:'catalog', payload:cat}; }
return null;

// cacheia o ÚLTIMO status de cada equipamento e repassa adiante
const m=msg;
if(m && m.topic && m.payload){
  const TOPICS=['conswatts','telemetry','temp','status'];
  if(TOPICS.indexOf(m.topic)>=0){
