// ==== GENÉRICO: monta a lista de ambientes para o supervisório ====
// Serve para QUALQUER Node-RED e QUALQUER fonte (postgres, mysql, http, file, inject...).
// Basta que a entrada contenha uma lista de registros com um campo de nome.
// Contrato de saída (fixo): { topic:"ambientesdb", payload:[{id,name,config}] }

var p = msg.payload;

// 1) acha o array de registros em vários formatos comuns
var rows =
    Array.isArray(p)                 ? p :
    (p && Array.isArray(p.rows))     ? p.rows :
    (p && Array.isArray(p.data))     ? p.data :
    (p && Array.isArray(p.result))   ? p.result :
    (p && Array.isArray(p.records))  ? p.records :
    (p && Array.isArray(p.ambients)) ? p.ambients :
    (p && Array.isArray(p.ambientes))? p.ambientes : [];

// 2) normaliza cada registro -> {id, name, config}
function pick(o){
  if (o == null) return null;
  if (typeof o === "string") return { name: o.trim() };
  var name = o.name || o.nome || o.title || o.titulo || o.label ||
             o.descricao || o.description || o.ambiente || o.ambient;
  if (!name) return null;
  return { id: (o.id != null ? o.id : undefined), name: ("" + name).trim(), config: o.config };
}

var out = [];
for (var i = 0; i < rows.length; i++){ var r = pick(rows[i]); if (r) out.push(r); }

return { topic: "ambientesdb", payload: out };

// Medidor de Energia: capta corrente e voltagem (qualquer saída do emitter) e manda pra tela.
// Filtra por message_type, então é seguro estar ligado em várias saídas.
var p = msg.payload || {};
var mt = p.message_type;
if (mt === 'current_update') {
  var _cur={ a:Number(p.a)||0, b:Number(p.b)||0, c:Number(p.c)||0, total:Number(p.total_current)||0 };
  try{ var _ms=global.get('meterState')||{}; if(!_ms[p.id]) _ms[p.id]={}; _ms[p.id].curr=_cur; global.set('meterState',_ms); }catch(e){}
  return { topic:'meter', payload:{ id:p.id, kind:'current', a:_cur.a, b:_cur.b, c:_cur.c, total:_cur.total } };
}
if (mt === 'voltage_update') {
  var v = p.voltage || {}, fp = p.fp || {};
  var _vol={ a:Number(v.a)||0, b:Number(v.b)||0, c:Number(v.c)||0, fpa:Number(fp.a)||0, fpb:Number(fp.b)||0, fpc:Number(fp.c)||0 };
  try{ var _ms2=global.get('meterState')||{}; if(!_ms2[p.id]) _ms2[p.id]={}; _ms2[p.id].volt=_vol; global.set('meterState',_ms2); }catch(e){}
  return { topic:'meter', payload:{ id:p.id, kind:'voltage', a:_vol.a, b:_vol.b, c:_vol.c, fpa:_vol.fpa, fpb:_vol.fpb, fpc:_vol.fpc } };
}
return null;

// Mapeia consumo dia/semana/mês + total por (slave_id:channel). Stateless.
var rows = Array.isArray(msg.payload) ? msg.payload : ((msg.payload && (msg.payload.rows||msg.payload.data)) || []);
var map = {};
for (var i=0;i<rows.length;i++){
  var r = rows[i]; if(r==null) continue;
  map[r.slave_id + ':' + r.channel] = {
    total: Number(r.total)||0,
    day:   Number(r.day)||0,
    week:  Number(r.week)||0,
    month: Number(r.month)||0,
    last:  r.last_ms ? Number(r.last_ms) : 0
  };
}
try{ global.set('pulsesState', map); }catch(e){}
return { topic:'pulsos', payload: map };

// TERMOSTATO SPLITAO — histerese por condensador + trava de seguranca. Tick ~30s.
// Regras: so atua se a Ventilacao (saida) estiver LIGADA e se o estado atual do
// condensador for DIFERENTE do objetivo. Liga quando T>=tOn, desliga quando T<=tOff
// (entre tOff e tOn = zona morta: mantem). TRAVA: se a Vent estiver desligada, o
// condensador e desligado. Roda no backend (independe de navegador).
const envs = global.get('envs')||[];
const cat  = global.get('catalog')||{};
const dmap = cat.deviceIds||{};
const tState = global.get('tempState')||{};
const cState = global.get('consState')||{};
const iState = global.get('itemState')||{};
const uiC  = global.get('uiCache')||{};
let ths = global.get('thermoState')||{};
const NOW = Date.now();
const DEBOUNCE = 20000; // ms minimos entre comandos do mesmo condensador

function rid(o){ if(!o) return null; if(o.deviceId!=null) return o.deviceId; if(o.device!=null && dmap[o.device]!=null) return dmap[o.device]; return null; }
function cmpOK(v,cmp,ref){ v=Number(v); ref=Number(ref); return (cmp==='<')?(v<ref):(v>ref); }

// estado on/off de uma fonte (espelha srcActive do front)
function srcOn(o){ if(!o) return null; var id=rid(o); if(id==null) return null;
  if(o.fonte==='temp'){ var d=tState[id]; if(!d||d.t==null) return null; return cmpOK(d.t,o.cmp||'>',o.valor||0); }
  if(o.fonte==='umidade'){ var du=tState[id]; if(!du||du.h==null) return null; return cmpOK(du.h,o.cmp||'>',o.valor||0); }
  if(o.fonte==='consumo'||o.fonte==='nivel'){ var w=cState[id]; if(w==null) return null; return cmpOK(w,o.cmp||'>',o.valor||0); }
  var tc=uiC['telemetry:'+id]; if(!tc||!tc.payload) return null; var chs=tc.payload.channels||[];
  var ch=chs.filter(function(c){return c.id===(o.channel||0);})[0]; if(!ch) return null;
  var v=(o.field==='input')?ch.input:(o.field==='ambos'?Math.max(Number(ch.input)||0,Number(ch.output)||0):ch.output);
  var on=(Number(v)||0)>=50; return o.invert?!on:on; }

// estado do condensador/vent: prioriza itemState (ja calculado no backend); senao srcOn
function stateOf(sid,o){ var s=iState[sid]; if(s&&s.state){ if(s.state==='on'||s.state==='present'||s.state==='open') return true; if(s.state==='off'||s.state==='absent'||s.state==='closed') return false; } return srcOn(o); }

// resolve o atuador do condensador (mesma logica do splCmd/motor)
function actuator(o){ var dev=o.actDevice||o.device;
  var id=o.actDevice?((o.actDeviceId!=null)?o.actDeviceId:(dmap[o.actDevice]!=null?dmap[o.actDevice]:null)):rid(o);
  var ch=o.actDevice?((o.actChannel!=null)?o.actChannel:0):((o.channel!=null)?o.channel:0);
  if(!dev||id==null) return null; return {deviceName:dev,id:id,channel:ch}; }

const cmds=[]; const logs=[];
envs.forEach(function(env){ (env.items||[]).forEach(function(it){
  if(it.type!=='splitao'||!it.bind) return; var b=it.bind;
  // temperatura do termostato do splitao
  var tid=(b.temp&&b.temp.deviceId!=null)?b.temp.deviceId:((b.temp&&b.temp.device!=null)?dmap[b.temp.device]:null);
  var td=(tid!=null)?tState[tid]:null; var T=(td&&td.t!=null)?Number(td.t):null;
  var ventOn=stateOf(it.id+'::vent', b.vent);
  [1,2].forEach(function(n){
    var o=b['cond'+n]; if(!o||!o.thermo||!o.thermo.on) return;
    var key=it.id+'::cond'+n; var last=ths[key]||0;
    var cur=stateOf(it.id+'::cond'+n, o);
    var act;
    // ---- TRAVA DE SEGURANCA: vent explicitamente desligada => condensador OFF ----
    if(ventOn===false){
      if(cur===true){ act=actuator(o); if(!act) return; if(NOW-last<DEBOUNCE) return;
        ths[key]=NOW; cmds.push({deviceName:act.deviceName,id:act.id,channel:act.channel,on:false,field:'output',_thermo:key}); logs.push('C'+n+' OFF(vent)'); }
      return; // com vent off nao roda histerese
    }
    if(ventOn!==true) return;                      // estado desconhecido -> nao faz nada
    // ---- histerese normal (vent ligada) ----
    var sp=Number(o.thermo.setpoint), hy=Number(o.thermo.hyst)||0;
    if(!isFinite(sp)) return; var tOn=sp, tOff=sp-hy;    // setpoint / histerese
    if(T==null) return;                            // sem leitura de temperatura
    var alvo=null; if(T>=tOn) alvo=true; else if(T<=tOff) alvo=false;
    if(alvo==null) return;                         // zona morta -> mantem
    if(cur===alvo) return;                          // so atua se diferente do objetivo
    act=actuator(o); if(!act) return;
    if(NOW-last<DEBOUNCE) return;
    ths[key]=NOW;
    cmds.push({ deviceName:act.deviceName, id:act.id, channel:act.channel, on:alvo, field:'output', _thermo:key });
    logs.push('C'+n+' '+(alvo?'ON':'OFF')+'@'+T+'\u00b0');
  });
}); });

envs.forEach(function(env){ (env.items||[]).forEach(function(it){
  if(it.type!=='fancoil'||!it.bind) return; var b=it.bind; var o=b.valve;
  if(!o||!o.thermo||!o.thermo.on) return;
  var fanOn=stateOf(it.id+'::fan', b.fan); if(fanOn!==true) return;
  var src=(o.thermo.src==='tempIns')?b.tempIns:b.tempRet;
  var tid=(src&&src.deviceId!=null)?src.deviceId:((src&&src.device!=null)?dmap[src.device]:null);
  var td=(tid!=null)?tState[tid]:null; var T=(td&&td.t!=null)?Number(td.t):null;
  var sp=Number(o.thermo.setpoint), hy=Number(o.thermo.hyst)||0;
  if(!isFinite(sp)) return; if(T==null) return; var tOn=sp, tOff=sp-hy;
  var alvo=null; if(T>=tOn) alvo=true; else if(T<=tOff) alvo=false; if(alvo==null) return;
  var cur=stateOf(it.id+'::valve', o); if(cur===alvo) return;
  var key=it.id+'::valve'; var last=ths[key]||0; var act=actuator(o); if(!act) return;
  if(NOW-last<DEBOUNCE) return; ths[key]=NOW;
  cmds.push({ deviceName:act.deviceName, id:act.id, channel:act.channel, on:alvo, field:'output', _thermo:key });
  logs.push('Valv '+(alvo?'ABRE':'FECHA')+'@'+T+'\u00b0');
}); });

global.set('thermoState', ths);
if(cmds.length){ node.status({fill:'green',shape:'dot',text:logs.join(' ')+' '+new Date().toLocaleTimeString()}); return [cmds.map(function(c){return {payload:c};})]; }
node.status({fill:'grey',shape:'ring',text:'sem acao '+new Date().toLocaleTimeString()});
return null;

// Fila da central ja aplicada (rate-limit 1/3s). Roteia cada comando ao destino correto.
var p = msg.payload || {};
if (p.method === 'infraredActivate' || (p.params && p.params.command_id != null)) {
  return [null, msg];   // IR/AC -> transmit-rfir-command
}
return [msg, null];      // canal (liga/desliga carga) -> activate-channel

// ENFILEIRA comando p/ a central, com COALESCING por alvo (o mais novo vence).
// EXCEÇÃO: comando do USUÁRIO (urgent) fura a fila e vai direto pro roteador AGORA.
var p = msg.payload; if(!p) return null;
function keyOf(pl){
  if(pl.method==='infraredActivate' || (pl.params && pl.params.command_id!=null)){
    return 'ir:'+((pl.params && pl.params.slave_id!=null)?pl.params.slave_id:'?');
  }
  return 'ch:'+pl.id+':'+(pl.channel!=null?pl.channel:0);
}
var k = keyOf(p);
var q = flow.get('cq') || [];

if(p.urgent){
  // remove qualquer enfileirado do mesmo alvo (o do usuário manda agora) e dispara já
  q = q.filter(function(x){ return x.key !== k; });
  flow.set('cq', q);
  flow.set('cqlast', Date.now());   // respeita o intervalo p/ o próximo da fila (protege a central)
  node.status({fill:'blue',shape:'dot',text:'URGENTE (usuário) \u00b7 '+q.length+' na fila'});
  return { payload: p };            // vai direto pro roteador
}

// normal (automação/agendamento/termostato): enfileira com coalescing
var found=false;
for(var i=0;i<q.length;i++){ if(q[i].key===k){ q[i].payload=p; q[i].at=Date.now(); found=true; break; } }
if(!found){ q.push({ key:k, payload:p, at:Date.now() }); }
flow.set('cq', q);
node.status({fill:'yellow',shape:'ring',text:q.length+' na fila'});
return null;

// LIBERA 1 comando por ~3s. A cada tick: poda da fila os comandos ja INVALIDOS
// (carga ja esta no estado desejado -> condicao mudou durante a espera) e, se passou
// o intervalo, envia o primeiro valido. Assim o obsoleto "sai da fila".
var MIN_GAP = 3000; // ms entre disparos
var now = Date.now();
var q = flow.get('cq') || [];
var uiC = global.get('uiCache') || {};

function chanState(id, ch){ var tc=uiC['telemetry:'+id]; if(!tc||!tc.payload) return null;
  var chs=tc.payload.channels||[]; var c=chs.filter(function(x){ return x.id===(ch!=null?ch:0); })[0];
  if(!c) return null; return (Number(c.output)||0)>=50; }
function desiredOf(p){ if(p.value!=null) return Number(p.value)>=50; if(p.output!=null) return Number(p.output)>=50; return null; }
function stillValid(item){ var p=item.payload; if(!p) return false;
  if(p.method==='infraredActivate' || (p.params && p.params.command_id!=null)) return true; // IR: malha aberta, sem validacao de estado
  var want=desiredOf(p); if(want==null) return true;
  var cur=chanState(p.id, p.channel);
  return !(cur!=null && cur===want); }   // INVALIDO se a carga ja esta no estado desejado

var before = q.length;
q = q.filter(stillValid);                 // poda os obsoletos da fila inteira
var dropped = before - q.length;

var last = flow.get('cqlast') || 0;
if(q.length && (now-last) >= MIN_GAP){
  var item = q.shift();
  flow.set('cqlast', now); flow.set('cq', q);
  node.status({fill:'green',shape:'dot',text:'enviou 1'+(dropped?(' \u00b7 '+dropped+' descartado(s)'):'')+' \u00b7 '+q.length+' na fila'});
  return { payload: item.payload };
}
flow.set('cq', q);
node.status({fill:(q.length?'yellow':'grey'),shape:'ring',text:(q.length?(q.length+' na fila'):'fila vazia')+(dropped?(' \u00b7 '+dropped+' descartado(s)'):'')});
return null;

const m = process.memoryUsage();
const MB = n => +(n/1024/1024).toFixed(1);
const caches = ['envs','itemState','consState','tempState','pulsesState','autos','catalog','uiCache','thermoState','autostate'];
const cacheKB = {}; let total = 0;
caches.forEach(function(k){ try { const s = JSON.stringify(global.get(k) || '').length; cacheKB[k] = +(s/1024).toFixed(1); total += s; } catch(e){ cacheKB[k] = null; } });
msg.payload = { rss_MB: MB(m.rss), heapUsed_MB: MB(m.heapUsed), heapTotal_MB: MB(m.heapTotal), external_MB: MB(m.external), caches_total_KB: +(total/1024).toFixed(1), caches_KB: cacheKB };
msg.topic = 'memoria_nodered';
node.status({ fill:'blue', shape:'dot', text: MB(m.rss)+' MB RSS | heap '+MB(m.heapUsed)+' | cache '+(total/1024).toFixed(0)+' KB' });
return msg;

const lines = String(msg.payload||'').split('\n');
const row = lines.find(function(l){ return /^Mem:/.test(l.trim()); });
if(row){ const p = row.trim().split(/\s+/); const total=+p[1], used=+p[2], free=+p[3], avail=+(p[6]!=null?p[6]:p[3]);
  const pct = total ? Math.round(used/total*100) : 0;
  msg.payload = { total_MB: total, used_MB: used, free_MB: free, available_MB: avail, used_pct: pct };
  msg.topic = 'memoria_sistema';
  node.status({ fill: (pct>90?'red':(pct>75?'yellow':'green')), shape:'dot', text: used+'/'+total+' MB ('+pct+'%) usado' });
} else { node.status({fill:'grey',shape:'ring',text:'sem saida do free -m'}); }
return msg;

// Recebe a config da tela, aplica no global (usado pelo polling) e grava em disco.
const cfg = msg.payload;
if(!cfg || !Array.isArray(cfg.devices)){ node.warn('Config inválida (sem devices), ignorada'); return null; }
global.set('modbusPollCfg', cfg);
node.status({fill:'green',shape:'dot',text:'aplicada '+new Date().toLocaleTimeString()});
// grava em arquivo (persistência entre restarts)
return { filename: '/data/modbus_poll_cfg.json', payload: JSON.stringify(cfg, null, 2) };

// No boot: lê o arquivo salvo e aplica no global. Se não existir, o polling usa o default embutido.
try{
  const cfg = JSON.parse(msg.payload);
  if(cfg && Array.isArray(cfg.devices)){
    global.set('modbusPollCfg', cfg); global.set('modbusCfgSource','arquivo');
    node.status({fill:'blue',shape:'dot',text:'config carregada do disco'});
    // devolve pra tela (se aberta) sincronizar
    return { topic:'loadcfg', payload: cfg };
  }
}catch(e){ node.status({fill:'grey',shape:'ring',text:'sem arquivo — usando default'}); }
return null;

// Polling round-robin — mapas de registradores FIXOS por modelo (Kron/Schneider).
// A config só traz os devices (endereço + modelo). Nada de registrador editável.
let currIndex = context.get('currIndex') || 0;
let lastPrioRead = context.get('lastPrioRead') || 0;

const MAPS = {
  kron:      { label:"Kron",      readType:"input", type:"none",    format:"float32_be_swap", registers:[{attributeName:"Tensão A",helexiaName:"voltage_a",startAddress:16,count:2,multiplyBy:1,divideBy:1},{attributeName:"Tensão B",helexiaName:"voltage_b",startAddress:18,count:2,multiplyBy:1,divideBy:1},{attributeName:"Tensão C",helexiaName:"voltage_c",startAddress:20,count:2,multiplyBy:1,divideBy:1},{attributeName:"Corrente A",helexiaName:"current_a",startAddress:22,count:2,multiplyBy:1,divideBy:1},{attributeName:"Corrente B",helexiaName:"current_b",startAddress:24,count:2,multiplyBy:1,divideBy:1},{attributeName:"Corrente C",helexiaName:"current_c",startAddress:26,count:2,multiplyBy:1,divideBy:1},{attributeName:"Potencia Ativa A",helexiaName:"power_a",startAddress:28,count:2,multiplyBy:1,divideBy:1},{attributeName:"Potencia Ativa B",helexiaName:"power_b",startAddress:30,count:2,multiplyBy:1,divideBy:1},{attributeName:"Potencia Ativa C",helexiaName:"power_c",startAddress:32,count:2,multiplyBy:1,divideBy:1},{attributeName:"Potencia Ativa Trifásica",helexiaName:"power",startAddress:12,count:2,multiplyBy:1,divideBy:1},{attributeName:"Potencia Reativa Trifásica",helexiaName:"power_reactive",startAddress:10,count:2,multiplyBy:1,divideBy:1},{attributeName:"Potencia Reativa A",helexiaName:"power_reactive_a",startAddress:34,count:2,multiplyBy:1,divideBy:1},{attributeName:"Potencia Reativa B",helexiaName:"power_reactive_b",startAddress:36,count:2,multiplyBy:1,divideBy:1},{attributeName:"Potencia Reativa C",helexiaName:"power_reactive_c",startAddress:38,count:2,multiplyBy:1,divideBy:1},{attributeName:"Fator de Potência Trifásico",helexiaName:"fp",startAddress:6,count:2,multiplyBy:1,divideBy:1},{attributeName:"Fator de Potência A",helexiaName:"fp_a",startAddress:46,count:2,multiplyBy:1,divideBy:1},{attributeName:"Fator de Potência B",helexiaName:"fp_b",startAddress:48,count:2,multiplyBy:1,divideBy:1},{attributeName:"Fator de Potência C",helexiaName:"fp_c",startAddress:50,count:2,multiplyBy:1,divideBy:1},{attributeName:"Energia Ativa Positiva",helexiaName:"kWh",startAddress:52,count:2,multiplyBy:1,divideBy:1},{attributeName:"Energia Reativa Positiva",helexiaName:"KVArh",startAddress:54,count:2,multiplyBy:1,divideBy:1}] },
  schneider: { label:"Schneider", readType:"hold",  type:"float32", format:"float32_be_swap", registers:[{attributeName:"Energia Ativa Positiva",helexiaName:"kWh",startAddress:2699,count:2,multiplyBy:1,divideBy:1},{attributeName:"Corrente A",helexiaName:"current_a",startAddress:2999,count:2,multiplyBy:1,divideBy:1},{attributeName:"Corrente B",helexiaName:"current_b",startAddress:3001,count:2,multiplyBy:1,divideBy:1},{attributeName:"Corrente C",helexiaName:"current_c",startAddress:3003,count:2,multiplyBy:1,divideBy:1},{attributeName:"Potencia Ativa A",helexiaName:"power_a",startAddress:3053,count:2,multiplyBy:1000,divideBy:1},{attributeName:"Potencia Ativa B",helexiaName:"power_b",startAddress:3055,count:2,multiplyBy:1000,divideBy:1},{attributeName:"Potencia Ativa C",helexiaName:"power_c",startAddress:3057,count:2,multiplyBy:1000,divideBy:1},{attributeName:"Potencia Ativa Trifásica",helexiaName:"power",startAddress:3059,count:2,multiplyBy:1000,divideBy:1},{attributeName:"Tensão A",helexiaName:"voltage_a",startAddress:3027,count:2,multiplyBy:1,divideBy:1},{attributeName:"Tensão B",helexiaName:"voltage_b",startAddress:3029,count:2,multiplyBy:1,divideBy:1},{attributeName:"Tensão C",helexiaName:"voltage_c",startAddress:3031,count:2,multiplyBy:1,divideBy:1},{attributeName:"Potência Reativa A",helexiaName:"power_reactive_a",startAddress:3061,count:2,multiplyBy:1,divideBy:1000},{attributeName:"Potência Reativa B",helexiaName:"power_reactive_b",startAddress:3063,count:2,multiplyBy:1,divideBy:1000},{attributeName:"Potência Reativa C",helexiaName:"power_reactive_c",startAddress:3065,count:2,multiplyBy:1,divideBy:1000},{attributeName:"Potência Reativa Trifásica",helexiaName:"power_reactive",startAddress:3067,count:2,multiplyBy:1000,divideBy:1},{attributeName:"Fator de Potência A",helexiaName:"fp_a",startAddress:3077,count:2,multiplyBy:1,divideBy:1},{attributeName:"Fator de Potência B",helexiaName:"fp_b",startAddress:3079,count:2,multiplyBy:1,divideBy:1},{attributeName:"Fator de Potência C",helexiaName:"fp_c",startAddress:3081,count:2,multiplyBy:1,divideBy:1},{attributeName:"Fator de Potência Trifásico",helexiaName:"fp",startAddress:3083,count:2,multiplyBy:1,divideBy:1}] }
};

const DEFAULT_CFG = { intervalMs:5000, priority:{enabled:false},
  devices:[ {address:4,name:'Geral',model:'kron',enabled:true}, {address:5,name:'Rede',model:'kron',enabled:true} ] };
let cfg = global.get('modbusPollCfg'); let usingDefault=false;
if(!cfg || !Array.isArray(cfg.devices) || cfg.devices.filter(function(x){return x.enabled;}).length===0){ cfg = DEFAULT_CFG; usingDefault=true; }
try{ var _act=cfg.devices.filter(function(x){return x.enabled;}).length; global.set('modbusActive',{n:_act, source: usingDefault?'PADRÃO(default)':(global.get('modbusCfgSource')||'?'), at:Date.now()}); }catch(e){}

// intervalo configurável (gate por tempo — o inject roda rápido e aqui limitamos)
const gateMs = Number(cfg.intervalMs) || ((Number(cfg.intervalSec)||5)*1000);
const lastTick = context.get('lastTick') || 0;
if(Date.now() - lastTick < gateMs){ return null; }
context.set('lastTick', Date.now());
const devices = (cfg.devices||[]).filter(d => d.enabled);

let all = [];
for(const dev of devices){
  const model = dev.model || dev.deviceType || 'kron';
  const m = MAPS[model]; if(!m) continue;
  for(const r of m.registers){
    all.push(Object.assign({}, r, {
      deviceName: dev.name, address: parseInt(dev.address), deviceType: model,
      readType: m.readType, type: m.type, format: m.format,
      multiplyBy: r.multiplyBy||1, divideBy: r.divideBy||1
    }));
  }
}
if(all.length === 0){ node.status({fill:'red',shape:'ring',text:'sem medidores ativos'}); return null; }

const now = Date.now();
const prio = cfg.priority || {};
const prioAttr = (prio.enabled) ? all.find(a => a.deviceName===prio.deviceName && a.attributeName===prio.attributeName) : null;
let curr;
if(prioAttr && (now - lastPrioRead) > (Number(prio.everyMs)||60000)){ curr = prioAttr; context.set('lastPrioRead', now); }
else { currIndex = (currIndex >= all.length-1) ? 0 : currIndex+1; curr = all[currIndex]; context.set('currIndex', currIndex); }

msg.currIndex = currIndex; msg.numAttributes = all.length;
msg.topic = curr.attributeName; msg.helexiaTopic = curr.helexiaName; msg.deviceName = curr.deviceName;
msg.deviceType = curr.deviceType; msg.format = curr.format; msg.multiplyBy = curr.multiplyBy; msg.divideBy = curr.divideBy;
msg.payload = { startAddress: curr.startAddress, count: curr.count, address: curr.address, type: curr.type, readType: curr.readType };
flow.set('mbLastRead', { address: curr.address, helexiaTopic: curr.helexiaName, deviceName: curr.deviceName,
  deviceType: curr.deviceType, format: curr.format, multiplyBy: curr.multiplyBy, divideBy: curr.divideBy });
msg.currAttribute = {
  startAddress: curr.startAddress, count: curr.count, attributeName: curr.attributeName,
  divideBy: curr.divideBy, helexiaName: curr.helexiaName, deviceName: curr.deviceName,
  address: curr.address, readType: curr.readType, type: curr.type,
  deviceType: curr.deviceType, multiplyBy: curr.multiplyBy
};
flow.set('mbLastAttr', msg.currAttribute);
node.status({fill:(usingDefault?'yellow':'green'),shape:'dot',text:(usingDefault?'⚠ PADRÃO ':'')+curr.deviceName+' ('+curr.deviceType+') · '+curr.attributeName});
return msg;

// Converte a resposta do Modbus conforme o formato de saída do nó:
//  - Kron (type "none"): payload = array[2] de registradores  -> faz FLOAT32 (word-swap).
//  - Schneider (type "float32"): o nó Modbus JÁ devolve um número -> usa direto.
// Depois: FP especial da Schneider (leading/lagging) + multiplyBy/divideBy.
const raw = msg.payload;
const last = flow.get('mbLastRead') || {};
const fmt   = msg.format     || last.format     || 'float32_be_swap';
const dtype = msg.deviceType || last.deviceType || 'kron';
const help  = msg.helexiaTopic || last.helexiaTopic || '';
const mult  = Number(msg.multiplyBy != null ? msg.multiplyBy : last.multiplyBy) || 1;
const div   = Number(msg.divideBy   != null ? msg.divideBy   : last.divideBy)   || 1;

function f32(hi, lo, le){ const bf=new ArrayBuffer(4), dv=new DataView(bf); dv.setUint16(0,hi&0xFFFF,false); dv.setUint16(2,lo&0xFFFF,false); return dv.getFloat32(0,le); }
function swap16(x){ return ((x&0xFF)<<8)|((x>>8)&0xFF); }
function calcPF(v){ if(v > 1) return 2 - v; if(v < -1) return -2 - v; return v; }

let val;
if(Array.isArray(raw)){
  // registradores crus -> FLOAT32
  if(raw.length < 2){ return null; }
  const a=raw[0], b=raw[1];
  switch(fmt){
    case 'float32_be':      val=f32(a,b,false); break;
    case 'float32_le':      val=f32(b,a,true);  break;
    case 'float32_be_swap':
    default:                val=f32(swap16(b),swap16(a),false);
  }
} else {
  // o nó Modbus já entregou o valor convertido (Schneider type float32)
  const n = Number(raw);
  if(isNaN(n)){ return null; }
  val = n;
}

// Schneider: Fator de Potência com tratamento leading/lagging
if(dtype==='schneider' && help.indexOf('fp')===0){ val = calcPF(val); }
// escala por registrador
val = val * mult / div;

msg.payload = val;
return msg;

// AGREGADOR: consolida por medidor e alimenta o ELEMENTO MEDIDOR do supervisório.
// Emite UMA mensagem consolidada por leitura (o $watch do dashboard descarta msgs em rajada).
const last = flow.get('mbLastRead') || {};
const id0  = (msg.address!=null) ? msg.address : last.address;
const help = msg.helexiaTopic || last.helexiaTopic || '';
const dname = msg.deviceName || last.deviceName || '';
if(id0==null || msg.payload==null || isNaN(Number(msg.payload))){ node.status({fill:'grey',shape:'ring',text:'sem id/valor'}); return null; }
const id  = 'MB'+id0;
const val = Number(msg.payload);

let A = global.get('modbusAgg') || {};
if(!A[id]) A[id] = {volt:{a:0,b:0,c:0}, curr:{a:0,b:0,c:0}, pot:{a:0,b:0,c:0}, fp:{a:1,b:1,c:1,total:1}, watts:0, extra:{}};
const d = A[id];
if(!d.volt) d.volt={a:0,b:0,c:0}; if(!d.curr) d.curr={a:0,b:0,c:0}; if(!d.pot) d.pot={a:0,b:0,c:0}; if(!d.fp) d.fp={a:1,b:1,c:1,total:1};
switch(help){
  case 'voltage_a': d.volt.a=val; break;
  case 'voltage_b': d.volt.b=val; break;
  case 'voltage_c': d.volt.c=val; break;
  case 'current_a': d.curr.a=val; break;
  case 'current_b': d.curr.b=val; break;
  case 'current_c': d.curr.c=val; break;
  case 'power':     d.watts=val;  break;
  case 'power_a':   d.pot.a=val;  break;
  case 'power_b':   d.pot.b=val;  break;
  case 'power_c':   d.pot.c=val;  break;
  case 'fp':        d.fp.total=val; break;
  case 'fp_a':      d.fp.a=val;   break;
  case 'fp_b':      d.fp.b=val;   break;
  case 'fp_c':      d.fp.c=val;   break;
  default:          d.extra[help]=val; break;
}
global.set('modbusAgg', A);

const cA=d.curr.a*1000, cB=d.curr.b*1000, cC=d.curr.c*1000, cT=(d.curr.a+d.curr.b+d.curr.c)*1000;
const curr = { a:cA, b:cB, c:cC, total:cT };
const volt = { a:d.volt.a, b:d.volt.b, c:d.volt.c, fpa:d.fp.a*255, fpb:d.fp.b*255, fpc:d.fp.c*255 };

// globais do supervisório (Motor lê daqui)
const ms = global.get('meterState') || {}; ms[id] = { curr:curr, volt:volt, pot:{a:d.pot.a,b:d.pot.b,c:d.pot.c} }; global.set('meterState', ms);
const cs = global.get('consState') || {}; cs[id] = d.watts; global.set('consState', cs);

node.status({fill:'green',shape:'dot',text:id+' · '+help+'='+val.toFixed(2)});
// UMA mensagem só, com tudo:
return { topic:'modbusmeter', payload:{ id:id, name:dname, watts:d.watts, curr:curr, volt:volt, pot:{a:d.pot.a,b:d.pot.b,c:d.pot.c} } };

// Publica a lista de medidores Modbus pro supervisório (nomes + ids namespaced "MB<addr>").
const cfg = (msg.payload && Array.isArray(msg.payload.devices)) ? msg.payload : (global.get('modbusPollCfg')||{});
const devs = (cfg.devices||[]).filter(x=>x.enabled);
const meters = devs.map(x=>({ name: 'Modbus \u00b7 '+x.name, id: 'MB'+x.address }));
return { topic:'modbusmeters', payload: meters };

// Mapa de nomes dos botões IR — robusto: chaveia por TODAS as combinações,
// pois o id que o AC usa pode ser command_id OU button_id, com ou sem slave.
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const bySlaveCmd={}, bySlaveBtn={}, byCmd={}, byBtn={};
rows.forEach(function(r){
  const nm=(r.button_name!=null?String(r.button_name):'').trim();
  if(!nm) return;
  const s=r.slave_id, c=r.command_id, bid=r.button_id;
  if(s!=null && c!=null)   bySlaveCmd[s+':'+c]=nm;
  if(s!=null && bid!=null)  bySlaveBtn[s+':'+bid]=nm;
  if(c!=null)   byCmd[c]=nm;
  if(bid!=null) byBtn[bid]=nm;
});
node.status({fill:(rows.length?'green':'red'),shape:'dot',text:rows.length+' linhas / '+Object.keys(byCmd).length+' cmds'});
node.warn('cmdnames: '+rows.length+' linhas do Postgres');
const out={ bySlaveCmd:bySlaveCmd, bySlaveBtn:bySlaveBtn, byCmd:byCmd, byBtn:byBtn };
global.set('cmdnames', out);
return { topic:'cmdnames', payload: out };

const cn=global.get('cmdnames');
if(cn) return { topic:'cmdnames', payload:cn };
return null;

// FORMATO ANTIGO (Helexia/Thingsboard). Recebe a msg LOGO APOS o no Modbus:
//  - Kron (type 'none'):   payload = array cru [hi,lo]  (o sistema antigo converte)
//  - Schneider (float32):  payload = numero ja convertido pelo no Modbus
// => passamos o payload COMO VEM (nao convertemos aqui), igual ao fluxo original.
var ca   = msg.currAttribute || flow.get('mbLastAttr') || {};
var last = flow.get('mbLastRead') || {};
function pick(){ for(var i=0;i<arguments.length;i++){ if(arguments[i]!=null) return arguments[i]; } return undefined; }

// currAttribute no MESMO formato/ordem do original
var caOut = { startAddress: ca.startAddress, count: ca.count, attributeName: ca.attributeName };
if(ca.multiplyBy != null && ca.multiplyBy !== 1) caOut.multiplyBy = ca.multiplyBy;
if(ca.divideBy   != null && ca.divideBy   !== 1) caOut.divideBy   = ca.divideBy;
caOut.helexiaName = ca.helexiaName;
caOut.deviceName  = ca.deviceName;
caOut.address     = ca.address;
caOut.readType    = ca.readType;
caOut.type        = ca.type;          // 'none' (Kron) / 'float32' (Schneider), igual ao original
caOut.deviceType  = ca.deviceType;

var out = {
  payload: msg.payload,                         // CRU (array Kron) ou numero (Schneider)
  topic: pick(msg.topic, ca.attributeName),
  currAttribute: caOut,
  currIndex: pick(msg.currIndex, 0),
  numAttributes: pick(msg.numAttributes, 0),
  helexiaTopic: pick(msg.helexiaTopic, ca.helexiaName, last.helexiaTopic),
  deviceName: pick(msg.deviceName, ca.deviceName, last.deviceName),
  deviceType: pick(msg.deviceType, ca.deviceType, last.deviceType),
  divideBy: pick(msg.divideBy, ca.divideBy, last.divideBy, 1),
  multiplyBy: pick(msg.multiplyBy, ca.multiplyBy, last.multiplyBy, 1)
};
return out;

var rows = Array.isArray(msg.payload) ? msg.payload : ((msg.payload && (msg.payload.rows||msg.payload.data)) || []);
var parse = function(v){ if(v==null) return null; if(typeof v==='string'){ try{ return JSON.parse(v); }catch(e){ return null; } } return v; };
var out = []; var got = [];
for(var i=0;i<rows.length;i++){
  var r=rows[i]; if(!r||r.chave==null) continue;
  var val=parse(r.valor); if(val==null) continue;
  if(r.chave==='envs'){ if(Array.isArray(val)&&val.length){ global.set('envs',val); out.push({topic:'load',payload:val}); got.push('envs'); } }
  else if(r.chave==='autos'){ if(Array.isArray(val)){ global.set('autos',val); out.push({topic:'autosload',payload:val}); got.push('autos'); } }
  else if(r.chave==='feriados'){ if(Array.isArray(val)){ global.set('feriados',val); out.push({topic:'feriadosload',payload:val}); got.push('feriados'); } }
  else if(r.chave==='alarmes'){ if(Array.isArray(val)){ out.push({topic:'alarmesload',payload:val}); got.push('alarmes'); } }
  else if(r.chave==='acl'){ if(val && typeof val==='object'){ global.set('acl',val); out.push({topic:'aclcfg',payload:val}); got.push('acl'); } }
  else if(r.chave==='modbuscfg'){ if(val && Array.isArray(val.devices)){ global.set('modbusPollCfg', val); global.set('modbusCfgSource','postgres'); got.push('modbuscfg'); } }
  else if(r.chave==='histcfg'){ if(val && typeof val==='object'){ var _dv=Math.max(1,Math.min(365,Math.round(Number(val.days)||30))); global.set('hist_days',_dv); out.push({topic:'histcfg',payload:{days:_dv}}); got.push('histcfg'); } }
  else if(r.chave==='tgcfg'){ if(val && typeof val==='object'){ if(val.token) global.set('tg_token',val.token); if(val.chat) global.set('tg_default',val.chat); global.set('tg_enabled', val.enabled!==false); out.push({topic:'tgcfg',payload:{token:val.token||'',chat:val.chat||'',enabled:val.enabled!==false}}); got.push('tgcfg'); } }
  else if(r.chave==='autostate'){ if(val && typeof val==='object'){ global.set('autostate',val); var _m={}; Object.keys(val).forEach(function(id){ if(val[id]&&val[id].lastFired) _m[id]=val[id].lastFired; }); out.push({topic:'autostatsnap',payload:_m}); got.push('autostate'); } }
}
node.status({fill: got.length?'green':'grey', shape:'dot', text:'Postgres: '+(got.join(', ')||'vazio (usando fallback)')});
out.push({topic:'pgdone', payload:{keys:got}});
return [out];

var key=msg.topic;
if(['envs','autos','feriados','alarmes'].indexOf(key)<0) return null;
var val=msg.payload;
if(!Array.isArray(val)) return null;
msg.params=[key, JSON.stringify(val)];
node.status({fill:'blue',shape:'dot',text:'upsert '+key+' ('+val.length+')'});
return msg;

msg.filename='/tmp/myio_mailer.js';
msg.payload="// Mini cliente SMTP (Gmail 465 TLS) usando só o módulo tls do Node. Lê os dados de /tmp/myio_maildata.b64.
const tls = require("tls"), fs = require("fs");
const USER = "automacaomyio@gmail.com", PASS = "claktocxaduupebs", FROM = USER;
const DATA = "/tmp/myio_maildata.b64";
let m;
try {
  const raw = fs.readFileSync(DATA, "utf8").trim();
  m = JSON.parse(Buffer.from(raw, "base64").toString("utf8"));
} catch (e) { console.error("dados invalidos: " + e.message); process.exit(1); }
const to = (m.to || []).filter(function(x){ return /@/.test(x); });
if (!to.length) { console.error("sem destinatario"); process.exit(1); }
const b = function(s){ return Buffer.from(String(s), "utf8").toString("base64"); };
const eol = "\r\n";
const email = "From: " + FROM + eol +
  "To: " + to.join(", ") + eol +
  "Subject: =?UTF-8?B?" + b(m.subject || "MYIO") + "?=" + eol +
  "MIME-Version: 1.0" + eol +
  "Content-Type: text/plain; charset=UTF-8" + eol + eol +
  (m.body || "") + eol + "." + eol;
let ri = 0, st = "greet", buf = "";
const c = tls.connect(465, "smtp.gmail.com", { servername: "smtp.gmail.com" });
c.setEncoding("utf8");
const w = function(x){ c.write(x + eol); };
c.on("data", function(d){
  buf += d; let i;
  while ((i = buf.indexOf(eol)) >= 0) {
    const ln = buf.slice(0, i); buf = buf.slice(i + 2);
    if (ln.length < 4) continue;
    if (ln[3] === "-") continue;
    const code = parseInt(ln.slice(0, 3), 10);
    if (code >= 400) { console.error("ERRO SMTP [" + st + "]: " + ln); process.exit(1); }
    step();
  }
});
function step(){
  if (st === "greet") { w("EHLO myio"); st = "ehlo"; }
  else if (st === "ehlo") { w("AUTH LOGIN"); st = "auth"; }
  else if (st === "auth") { w(b(USER)); st = "user"; }
  else if (st === "user") { w(b(PASS)); st = "pass"; }
  else if (st === "pass") { w("MAIL FROM:<" + FROM + ">"); st = "mail"; }
  else if (st === "mail") { w("RCPT TO:<" + to[ri++] + ">"); st = (ri < to.length) ? "mail" : "rcpt"; }
  else if (st === "rcpt") { w("DATA"); st = "data"; }
  else if (st === "data") { c.write(email); st = "dot"; }
  else if (st === "dot") { w("QUIT"); st = "quit"; console.log("EMAIL OK -> " + to.join(", ")); }
  else if (st === "quit") { c.end(); process.exit(0); }
}
c.on("error", function(e){ console.error("CONN ERRO: " + e.message); process.exit(1); });
setTimeout(function(){ console.error("timeout SMTP"); process.exit(1); }, 20000);
";
return msg;

var m=global.get('meterIdMap')||{}; var p=msg.payload;
if(msg.topic==='modbusmeter' && p && p.name!=null && p.id!=null){ m[p.name]=p.id; m['Modbus · '+p.name]=p.id; }
else if(msg.topic==='modbusmeters' && Array.isArray(p)){ p.forEach(function(x){ if(x && x.name!=null && x.id!=null){ m[x.name]=x.id; m['Modbus · '+x.name]=x.id; } }); }
global.set('meterIdMap', m); return null;

var st=global.get('autostate')||{}; var map={};
Object.keys(st).forEach(function(id){ if(st[id] && st[id].lastFired) map[id]=st[id].lastFired; });
return {topic:'autostatsnap', payload:map};

if(msg.topic!=='autostat') return null;
var st=global.get('autostate')||{};
msg.params=['autostate', JSON.stringify(st)];
