let bufferA = Buffer.alloc(2);
let bufferB = Buffer.alloc(2);

bufferA.writeUint16BE(a, 0);
bufferB.writeUint16BE(b, 0);

bufferA = bufferA.reverse();
bufferB = bufferB.reverse();

let newA = bufferA.readUint16BE(0);
let newB = bufferB.readUint16BE(0);

const converted2 = convertFLOAT32([newB, newA]);

msg.payload = converted2;

return msg;

